function maskP1c() 
{
    var st = set();

    var codes = f('P1b').domainValues();
    for (var i = 0; i < codes.length; i++) 
    {
        var code = codes[i];
        if (f('P1b').item(code).toBoolean() && f('P1a',code).get()>1)
        {
            f('P1aresp',code).set(f('P1a',code).get());
            st.add(code);
        }
    }
    return st;
}

